// План specs/gps-workflow.md 1.1 (кейс .qa/tests/gps-workflow/GW-01). PROD, gps (компания «בדיקה»), десктоп, EN.
// @prod-safe: счёт НЕ сохраняется (Create Invoice не нажимается); у сообщения уже есть Job — второй Job не создаётся.
import { test, expect } from '../../fixtures';
import { ROLE, prepare, openGpsAll, openMessage, openJobFromDialog, messageItem } from './gps-helpers';

const MESSAGE = /^QA-Mark Stone\b/; // «Job created», без счёта (данные QA 02.11 / 12.11)

test.describe('GPS Workflow — Create invoice из сообщения (#f45391)', () => {
  test('Job created message: Create invoice opens unsaved InvoiceForm for the same job, leaving keeps "Job created" #f45391 @desktop @prod-safe', async ({ asUser }) => {
    test.setTimeout(120_000);
    const page = await asUser(ROLE);
    await prepare(page);

    // До: статус Job created, кнопки Open job + Create invoice, без Open invoice
    await openGpsAll(page);
    await expect(messageItem(page, MESSAGE)).toContainText('Job created');
    let dialog = await openMessage(page, MESSAGE);
    await expect(dialog.getByText('Job created', { exact: true })).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'Create invoice' })).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'Open invoice' })).toHaveCount(0);
    const jobId = await openJobFromDialog(page, dialog);

    // Create invoice → несохранённая форма для ЭТОЙ же работы (from_job = id из Open job) и этого сообщения
    await openGpsAll(page);
    dialog = await openMessage(page, MESSAGE);
    await dialog.getByRole('button', { name: 'Create invoice' }).click();
    await page.waitForURL(/\/InvoiceForm\?.*from_job=/i, { timeout: 30_000 });
    const url = new URL(page.url());
    expect(url.searchParams.get('from_job'), 'Create invoice не создаёт вторую Job').toBe(jobId);
    expect(url.searchParams.get('from_text'), 'форма привязана к сообщению').toBeTruthy();
    await expect(page.getByText(/Invoice number:\s*N\/A/)).toBeVisible({ timeout: 20_000 });
    await expect(page.getByRole('button', { name: 'Create Invoice' })).toBeVisible();

    // Выход без сохранения → статус остаётся Job created, можно снова Create invoice
    await openGpsAll(page);
    await expect(messageItem(page, MESSAGE)).toContainText('Job created');
    await expect(messageItem(page, MESSAGE)).not.toContainText(/Invoice (started|created)/);
    dialog = await openMessage(page, MESSAGE);
    await expect(dialog.getByText('Job created', { exact: true })).toBeVisible();
    await expect(dialog.getByText(/Invoice started/)).toHaveCount(0);
    await expect(dialog.getByRole('button', { name: 'Create invoice' })).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'Open invoice' })).toHaveCount(0);
  });
});
